module sva_case(input logic clk, output logic done);
  logic [2:0] tick = 0;
  always @(posedge clk) if (tick != 3'd5) tick <= tick + 1'b1;
  function automatic [3:0] hexd(input [7:0] c);
    hexd = (c >= "A") ? 4'(c - "A" + 8'd10) :
           (c >= "0" && c <= "9") ? 4'(c - "0") : 4'h0;
  endfunction
  // position of the current sample in the rows below (the last one is held past the end)
  wire [31:0] row_idx = (tick < 3'd5) ?
                          32'(tick) : 32'd4;
  wire [71:0] ROW_v = "0 1 3 8 F";
  wire [3:0] v = 4'({hexd(ROW_v[8*(8-2*row_idx) +: 8])});
  wire [71:0] ROW_b = ". . . . .";
  wire b = (ROW_b[8*(8-2*row_idx) +: 8] == "1");
  assign done = (tick == 3'd5);
  p: assert property (@(posedge clk) $onehot(v) |-> b)
    $display("SVA_PASS bitcount/onehot_antecedent sample=%0d", $sampled(tick));
    else $display("SVA_FAIL bitcount/onehot_antecedent sample=%0d", $sampled(tick));
